    [9651]={name="Gryphon Rider's Stormhammer",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!",proc="Chance on hit: Blasts a target for 91 to 125 Nature damage."},
