    [9680]={name="Tok'kar's Murloc Shanker",quality=2,ilvl=43,sourceType="quest_reward",instructions="Reward from the quest 'Threat From the Sea' - pick it over the other choices. In Swamp of Sorrows.",zone="Swamp of Sorrows",questName="Threat From the Sea",lore="Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."},
