    [10638]={name="Long Draping Cape",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim' - pick it over the other choices. In Undercity.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10653]={name="Trailblazer Boots",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Horde Presence' - pick it over the other choices. In The Barrens.",zone="The Barrens",questName="Horde Presence",lore="This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."},
    [10703]={name="Fiendish Skiv",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'Challenge Overlord Mok'Morokk' - pick it over the other choices. In Dustwallow Marsh.",zone="Dustwallow Marsh",questName="Challenge Overlord Mok'Morokk",lore="You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny! You tell me when ready for good beating."},
    [10727]={name="Goblin Dragon Gun",quality=1,ilvl=48,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",proc="Use: Deals 61 to 69 fire damage for 10 sec to all targets in a cone in front of the engineer using the weapon.   That is unless it explodes..... (5 Min Cooldown)"},
    [10741]={name="Lordrec Helmet",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Rise, Obsidion!' - pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="Rise, Obsidion!",lore="It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."},
    [10748]={name="Wanderlust Boots",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Mazen's Behest' - pick it over the other choices. In Stormwind City.",zone="Stormwind City",questName="Mazen's Behest",lore="Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"},
