    [23038]={name="Band of Unnatural Forces",quality=4,ilvl=85,reqLevel=60,sourceType="boss_drop",instructions="Drops from Loatheb in Naxxramas.",zone="Naxxramas",npc="Loatheb",lore="A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."},
    [23041]={name="Slayer's Crest",quality=4,ilvl=90,reqLevel=60,sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber.",proc="Use: Increases attack power by 260 for 20 sec. (2 Min Cooldown)"},
    [23060]={name="Bonescythe Ring",quality=4,ilvl=92,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [23206]={name="Mark of the Champion",quality=4,ilvl=90,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Kel'Thuzad' - pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Fall of Kel'Thuzad",lore="Struck for the war against the Scourge and the Old Gods. It does nothing at all against anything else, which is the point of the mark."},
    [23323]={name="Crown of the Fire Festival",quality=1,ilvl=1,sourceType="quest_reward",instructions="Reward from the quest 'A Thief's Reward'.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
    [23324]={name="Mantle of the Fire Festival",quality=1,ilvl=1,sourceType="quest_reward",instructions="Reward from the quest 'Wild Fires in the Eastern Kingdoms'.",questName="Wild Fires in the Eastern Kingdoms",seasonal=true,lore="Our celebration of the flame is spread throughout the land. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue."},
